tb(12,'MCQ',2,'NH₃ + H₂SO₄ বিক্রিয়াটি—\n(i) একটি প্রশমন বিক্রিয়া\n(ii) উৎপাদ উদ্ভিদের একটি গুরুত্বপূর্ণ পুষ্টি উপাদান\n(iii) উৎপাদের জলীয় দ্রবণের pH এর মান 7 এর চেয়ে বেশি\nনিচের কোনটি সঠিক?',308,options=['i ও ii','ii ও iii','i ও iii','i, ii ও iii'],correct='A',solution='পূর্ণ প্রশমনে2NH₃+H₂SO₄→(NH₄)₂SO₄। এটি নাইট্রোজেন/সালফার সরবরাহকারী সার। NH₄⁺-এর অম্লীয় জলবিশ্লেষণে সাধারণ জলীয় দ্রবণ অম্লীয়, pH>7 নয়। সার সরাসরি কত দিতে হবে তার নির্দেশ নয়।')
tb(12,'MCQ',3,'কোনটি রঙিন পদার্থকে বর্ণহীন করে?',308,options=['NaOH','Ca(OCl)Cl','HCl','CH₃COOH'],correct='B',solution='Ca(OCl)Cl হলো ব্লিচিং পাউডারের প্রচলিত পাঠ্য সংকেত; বাস্তব পণ্য মিশ্র প্রকৃতির। উপযুক্ত শর্তে হাইপোক্লোরাইট জারণের মাধ্যমে রং নষ্ট করতে পারে। সব রঞ্জক বা সব পৃষ্ঠে একই প্রভাব নয়; অম্ল/অ্যামোনিয়ার সঙ্গে মেশানো বিপজ্জনক।')
tb(12,'MCQ',4,'জমিতে ইউরিয়া প্রয়োগ করলে কোন আয়ন উদ্ভিদ দ্বারা পরিশোষিত হয়?',309,options=['OH⁻','NH₄⁺','H⁺','Cl⁻'],correct='B',solution='প্রদত্ত বিকল্পে NH₄⁺ সঠিক। ইউরিয়া মাটিতে রূপান্তরিত হয়ে অ্যামোনিয়াম দেয়, পরে নাইট্রিফিকেশনে নাইট্রেটও হতে পারে। উদ্ভিদ NH₄⁺ ও NO₃⁻ উভয়ভাবেই N নিতে পারে; শুধু একমাত্র আয়ন বলার দাবি নয়।')
tb(12,'CQ',1,'দশম শ্রেণির ছাত্র শাওন টিউবওয়েলের পানিতে সাবান দিয়ে কাপড় ধুয়ে দেখল সেটি তেমন পরিষ্কার হয়নি এবং ফেনাও ভালো হয়নি। তার বন্ধু রিয়াদকে কথাটি জানালে রিয়াদ তাকে ডিটারজেন্ট ব্যবহার করার পরামর্শ দিল।',309,parts=['সাবান কী?','গ্লাস ক্লিনার ও টয়লেট ক্লিনারের পার্থক্য লেখো।','শাওন প্রথমে যে পদার্থ দিয়ে কাপড় পরিষ্কার করার চেষ্টা করেছিল তার পরিষ্কারক কৌশল বর্ণনা করো।','রিয়াদ কাপড় পরিষ্কার করার জন্য শাওনকে যে পরিষ্কারক সামগ্রীর পরামর্শ দিয়েছিল সেটি কার্যকর হওয়ার কারণ যুক্তিসহ ব্যাখ্যা দাও।'],solutions=['উচ্চতর ফ্যাটি এসিডের Na/K লবণকে সাধারণভাবে সাবান বলে।','পাঠ্য গ্লাসক্লিনারে জলীয় অ্যামোনিয়াভিত্তিক ক্ষারীয় মডেল, আর টয়লেটক্লিনারের উপাদান পণ্যভেদে অম্লীয় স্কেলরিমুভার বা পৃথক হাইপোক্লোরাইটভিত্তিক পণ্য হতে পারে। একটিকে অন্যটির সঙ্গে মেশানোর নির্দেশ নয়; বিশেষত ব্লিচের সঙ্গে অম্ল বা অ্যামোনিয়া মেশানো যাবে না।','সাবানের দীর্ঘ অপোলার লেজ তেল-গ্রিজে, আয়নিক জলাকর্ষী মাথা পানির দিকে থাকে। নড়াচড়ায় তেলের ফোঁটা ভেঙে চারপাশে সাবান আয়নের আবরণে ছড়িয়ে যায়; ধোয়ার পানির সঙ্গে অপসারিত হয়। ময়লা নতুন মৌলে পরিণত হয় না।','খর পানিতে Ca²⁺/Mg²⁺ সাবানের অদ্রবণীয় লবণ/গাদ তৈরি করে। প্রচলিত সিন্থেটিক ডিটারজেন্টের উপযুক্ত সারফ্যাক্ট্যান্ট এই আয়নগুলোর সঙ্গে সাবানের মতো সহজে গাদ না করায় খর পানিতেও কার্যকর হতে পারে। সব ব্র্যান্ড/সব বর্জ্যের পরিবেশপ্রভাব একই নয়।'])
for n,(text,solution)in enumerate([
 ('সাবান প্রস্তুতিতে NaCl ব্যবহার করা হয় কেন? ব্যাখ্যা করো।','NaCl যোগে দ্রবণে সাবানের দ্রাব্যতা কমে আলাদা হতে সাহায্য করে—স্যাল্টিং আউট। সাধারণ সাবান তৈরির মূল বিক্রিয়ক তেল/চর্বি ও NaOH/KOH; NaCl যোগ নিজেই সাবানায়ন নয়। ঘরোয়া ক্ষার ব্যবহারের রেসিপি নয়।'),
 ('অতিরিক্ত ডিটারজেন্ট ব্যবহার জলাশয়ের জন্য ক্ষতিকর কেন? ব্যাখ্যা করো।','উচ্চ সারফ্যাক্ট্যান্টমাত্রা জলজ প্রাণীর ক্ষতি/ফেনা সৃষ্টি করতে পারে। ফসফেটযুক্ত পণ্য অতিরিক্ত গেলে ইউট্রোফিকেশনে অবদান রাখতে পারে; সব ডিটারজেন্টে ফসফেট থাকে না। উপযুক্ত বর্জ্যশোধন ও পরিমিত ব্যবহার দরকার।'),
 ('প্রসাধনীর pH 4.8 থেকে 5.5 এর মধ্যে হয় কেন? ব্যাখ্যা করো।','বইটি ত্বক-সংস্পর্শী অনেক প্রসাধনীর জন্য ত্বকের মৃদু অম্লীয় পৃষ্ঠের সঙ্গে সামঞ্জস্যের একটি উদাহরণ দিয়েছে। সব প্রসাধনী/সব ত্বক/অঙ্গের জন্য একই বাধ্যতামূলক pH নয়। উপযোগিতা ফর্মুলেশন, সহনশীলতা ও পণ্যনির্দেশের উপরও নির্ভর করে; pH একাই নিরাপত্তার প্রমাণ নয়।')],1):tb(12,'SQ',n,text,309,solution=solution)
